int findMaxConsecutiveOnes(vector<int>& nums) {
    int best = 0, current = 0;
    for (int x : nums) {
        if (x == 1) {
            current++;
            best = max(best, current);
        } else current = 0;
    }
    return best;
}
// USER_SOLUTION_END

